        if(!bufferBigEnough) {
            Assert.assertFalse(res);
            return;
        }
        Assert.assertTrue(res);
        buffer.flip();
        Assert.assertTrue(((1 << 7) & buffer.get(0)) != 0); //make sure the huffman bit is set
