public static void verifyToken(HttpString header) {
        int length = header.length();
        for(int i = 0; i < length; ++i) {
            byte c = header.byteAt(i);
            if(!ParserUtils.isTokenChar(c)) {
                throw UndertowMessages.MESSAGES.invalidToken(c);
            }
